#include <bits/stdc++.h>
#define EXTREME_INF 17446744073709551616ULL
#define ULL unsigned long long
using namespace std;

ULL M, nCount, kCount, dpStates[19][300005];
ULL factArr[300005], invFactArr[300005];

ULL fast_pow(ULL base, ULL exp) {
    ULL res = 1ULL;
    while (exp > 0) {
        if (exp & 1ULL) res = (res * base) % M;
        base = (base * base) % M;
        exp >>= 1ULL;
    }
    return res;
}

ULL nCr(int a, int b) {
    return (((factArr[a] * invFactArr[b]) % M) * invFactArr[a - b]) % M;
}

ULL compute() {
    int i, j, mask;
    factArr[0] = 1ULL;
    ULL limit = max(nCount, kCount);
    for (i = 1; i <= limit; i++) {
        factArr[i] = (factArr[i - 1] * (ULL)i) % M;
    }
    invFactArr[limit] = fast_pow(factArr[limit], M - 2ULL);
    for (i = limit - 1; i >= 0; i--) {
        invFactArr[i] = (invFactArr[i + 1] * (ULL)(i + 1)) % M;
    }
    for (i = 1; i <= nCount; i++) {
        dpStates[1][i] = invFactArr[i];
    }
    ULL totalRes = dpStates[1][nCount] * nCr(kCount, 1) % M;
    int maxIter = min(18, (int)kCount);
    for (i = 2; i <= maxIter; i++) {
        for (j = nCount; j > 0; j = (j - 1) & nCount) {
            if (!dpStates[i - 1][j]) continue;
            int rem = nCount ^ j;
            for (mask = rem; mask > j; mask = (mask - 1) & rem) {
                dpStates[i][j ^ mask] += dpStates[i - 1][j] * invFactArr[mask];
                if (dpStates[i][j ^ mask] > EXTREME_INF) dpStates[i][j ^ mask] %= M;
            }
        }
        for (j = nCount; j > 0; j = (j - 1) & nCount) {
            if (dpStates[i][j] >= M) dpStates[i][j] %= M;
        }
        ULL resVal = dpStates[i][nCount] * nCr(kCount, i) % M;
        resVal = (resVal * factArr[i]) % M;
        totalRes = (totalRes + resVal >= M ? totalRes + resVal - M : totalRes + resVal);
    }
    totalRes = (totalRes * factArr[nCount]) % M;
    return totalRes;
}

int main() {
    cin >> nCount >> kCount >> M;
    ULL ans = fast_pow(kCount, nCount);
    if (nCount % 2 == 0) ans = (ans - compute() + M) % M;
    cout << ans << endl;
    return 0;
}
